def bracket(q):
    """Smallest positive integer k with |q| > 1/k, EXACTLY.  None if q == 0."""
    q = sp.Abs(sp.cancel(q))
    if q == 0:
        return None
    n, d = sp.fraction(q)
    k = sp.Integer(d) // sp.Integer(n) + 1
    return int(k) if q > R(1, k) else int(k) + 1


def partitions_of(items: tuple) -> list:
    items = tuple(items)
    if not items:
        return [[]]
    first, rest = items[0], items[1:]
    out = []
    for p in partitions_of(rest):
        for i in range(len(p)):
            out.append(p[:i] + [tuple(sorted(p[i] + (first,), key=str))]
                       + p[i + 1:])
        out.append([(first,)] + p)
    return [sorted(p, key=str) for p in out]


