class Fix:
    """One extent, with the 172-specific record machinery over b171.Site."""

    def __init__(self, tag: str, cover_t: int, lx: int):
        self.tag = tag
        self.site = b171.Site(tag, cover_t, lx)
        s = self.site
        self.lx, self.tstar = s.lx, s.tstar
        self.free_levels = s.free_levels
        self.slots = s.free_levels[:-1]
        self.cells = tuple((t, x) for t in s.free_levels for x in range(s.lx))
        self.free_rows = tuple(s.lx * (t % s.T) + x
                               for t in s.free_levels for x in range(s.lx))
        self._env: dict = {}

    def env(self, records: dict = None, mode: str = "xgraded", **kw):
        records = records or {}
        key = (mode, tuple(sorted((c, str(v)) for c, v in records.items())),
               tuple(sorted((k, str(v)) for k, v in kw.items())))
        if key not in self._env:
            s = self.site
            self._env[key] = b171.Env(
                s, s.bench.Q.subs(s.sub(mode=mode, records=records, **kw)), "e")
        return self._env[key]

    def w(self, cells):
        """Unnormalized Gibbs weight of a record SET: the joint pin (H1-172a)."""
        return self.env({c: Z0 for c in cells}).trace(BEST, self.tstar)

    def B(self, records: dict = None, level: int = None):
        return self.env(records or {}).block(
            BEST, self.tstar if level is None else level)

    def profile(self, records: dict = None, level: int = None):
        return self.env(records or {}).profile(
            BEST, self.tstar if level is None else level)

    def free_block(self, records: dict = None):
        """herm(Q^{-1}) compressed to ALL free-level rows: the free-cell block."""
        e = self.env(records or {})
        Qi = e.inv("Q")
        r = self.free_rows
        n = len(r)
        return sp.Matrix(n, n, lambda i, j: sp.expand(
            (Qi[r[i], r[j]] + sp.conjugate(Qi[r[j], r[i]])) / 2))


def merge_subsets(f: Fix, deep: bool) -> tuple:
    """The PRE-REGISTERED merge enumeration.

    At 8x4 --deep runs the COMPLETE 2^8 - 1 = 255 nonempty subsets, which
    determines the defect of every one of the Bell(8) = 4140 coarse-grainings
    because the defect is a per-cell quantity.  At 12x4 the 65535 subsets are
    infeasible, so the DISCLOSED STRUCTURED SAMPLE is the slice-aligned
    sublattice.  The BASELINE runs singletons + two-cell merges + the top cell
    at both extents, which is exactly what the forced-sign bracket and the
    primitive 1/|A_cell| defect are read from.
    """
    if f.tag == "8x4" and deep:
        return tuple(frozenset(c) for k in range(1, len(f.cells) + 1)
                     for c in itertools.combinations(f.cells, k))
    out = {frozenset([c]) for c in f.cells}
    for pair in itertools.combinations(f.cells, 2):
        if f.tag == "8x4" or pair[0][0] == pair[1][0]:
            out.add(frozenset(pair))
    if deep:
        for t in f.free_levels:
            lev = [(t, x) for x in range(f.lx)]
            for k in (3, 4):
                for comb in itertools.combinations(lev, k):
                    out.add(frozenset(comb))
        for x in range(f.lx):
            out.add(frozenset((t, x) for t in f.free_levels))
    out.add(frozenset(f.cells))
    return tuple(sorted(out, key=lambda s: (len(s), sorted(s))))


# ---------------------------------------------------------------------------
# B. the banners, the bench and the provenance reproduction
# ---------------------------------------------------------------------------
def banner_probe(fixes: dict) -> dict:
    """The convention collision, the imposed-object banner, the bench anchors."""
    convention = b170.convention_probe()       # the LANDED collision instrument
    out = {"convention": convention,
           "imposed_objects": len(IMPOSED_OBJECTS),
           "registered_objects": len(REGISTERED_OBJECTS),
           "owner_decisions": len(OWNER_DECISIONS),
           "readings": len(READINGS),
           "sites": {}}
    for tag, f in fixes.items():
        s = f.site
        sub = s.sub()
        Qn = sp.expand(s.bench.Q.subs(sub))
        shears = set(b166.free_shears(s.fx, s.c))
        B = sp.expand(f.B())
        out["sites"][tag] = {
            "bench_is_landed": is_zero(Qn - sp.expand(s.bench.Q.subs(sub))),
            "T_phys": s.T,
            "lx": s.lx,
            "tstar": s.tstar,
            "free_levels": len(f.free_levels),
            "free_cells": len(f.cells),
            "alphabet_closed_form": L_X[tag] * (PHYS_T[tag] - 2),
            "alphabet_matches": L_X[tag] * (PHYS_T[tag] - 2) == len(shears),
            "cm_site_size": s.lx,
            "coarse_graining_nonvacuous": s.lx >= 3,
            "w9_rs_hermitian": is_zero(B - B.H),
            "w9_rs_inertia": hermitian_inertia(B, f"W9RS{tag}"),
            "inverse_residual_zero": is_zero(
                sp.expand(Qn * f.env({}).inv("Q")) - sp.eye(s.N)),
        }
    # THE PARTITION LATTICE of the 4-site alphabet, counted TWO ways.
    parts = partitions_of(tuple(range(L_X[BENCH_TAG])))
    ref_pairs = [(p, q) for p in parts for q in parts
                 if p != q and all(any(set(b) <= set(c) for c in q) for b in p)]
    bell = (1, 1, 2, 5, 15)
    zeta = sum(sp.prod([bell[len(b)] for b in part]) for part in parts)
    out["lattice"] = {
        "partitions": len(parts),
        "refinement_pairs": len(ref_pairs),
        "bell_product_count": int(zeta),
        "counts_agree": len(parts) == 15 and len(ref_pairs) == 45
        and zeta - 15 == 45,
    }
    # THE PROVENANCE GATE: all 32 rows of the CORRECTED b171 profile table,
    # reproduced entry for entry by this block's independent recomputation off
    # the committed chain.
    namespace: dict = {}
    exec(compile(PROFILE_TABLE.read_text(encoding="utf-8"),
                 str(PROFILE_TABLE), "exec"), namespace)
    reference = {(row[0], row[1]): row[2] for row in namespace["ROWS"]}
    mine = {}
    for tag, f in fixes.items():
        lv = f.free_levels[:2]
        for x1 in range(f.lx):
            for x2 in range(f.lx):
                p = f.profile({(lv[0], x1): Z0, (lv[1], x2): Z0})
                mine[(tag, (x1, x2))] = tuple(
                    (int(sp.fraction(sp.cancel(v))[0]),
                     int(sp.fraction(sp.cancel(v))[1])) for v in p)
    hits = sum(1 for key, value in reference.items()
               if key in mine and mine[key] == tuple(tuple(x) for x in value))
    out["provenance"] = {
        "reference_rows": len(reference),
        "recomputed_rows": len(mine),
        "hits": hits,
        "mismatches": len(reference) - hits,
        "rows_match": hits == len(reference) == 32 and len(mine) == 32,
        "table_alphabet": namespace["ALPHABET"]["closed_form"],
    }
    return out


# ---------------------------------------------------------------------------
# C. the four-reading census, with the vacuity/force structure asserted
# ---------------------------------------------------------------------------
def census_probe(fixes: dict, deep: bool) -> dict:
    out: dict = {}
    lx = L_X[BENCH_TAG]
    parts = partitions_of(tuple(range(lx)))
    # A1 VACUITY, symbolic: the projector identity in the FREE ENTRIES of an
    # ARBITRARY matrix, Hermitian or not, at 4x4 and 8x8.  The instrument
    # cannot produce a defect, so its zero is NOT evidence.
    gsym = sp.Matrix(lx, lx, lambda i, j: sp.Symbol(f"g_{i}{j}"))
    vac4 = all(
        sp.expand(sp.trace(gsym * sp.diag(
            *[1 if i in blk else 0 for i in range(lx)]))
            - sum(gsym[a, a] for a in blk)) == 0
        for part in parts for blk in part)
    g8 = sp.Matrix(8, 8, lambda i, j: sp.Symbol(f"h_{i}{j}"))
    vac8 = all(
        sp.expand(sp.trace(g8 * sp.diag(*[1 if i in S else 0
                                          for i in range(8)]))
                  - sum(g8[a, a] for a in S)) == 0
        for S in [frozenset(c) for k in range(1, 9)
                  for c in itertools.combinations(range(8), k)])
    # ... and in a NON-COMMUTING frame.  DISCLOSED (hygiene defect 4): the
    # rotated leg is measured in the REAL-ORTHOGONAL frame only; the
    # Gaussian-rational unitary frame is verified a resolution of the identity
    # and no more.  The conclusion survives on LINEARITY OF THE TRACE, which is
    # what makes the frame leg vacuous TWICE OVER (the checker's strengthening).
    c35, s35 = R(3, 5), R(4, 5)
    U = sp.Matrix([[c35, -s35, 0, 0], [s35, c35, 0, 0],
                   [0, 0, c35, -s35], [0, 0, s35, c35]])
    rot = [sp.expand(U * sp.diag(*[1 if i == a else 0 for i in range(lx)]) * U.T)
           for a in range(lx)]
    UC = sp.diag(sp.Matrix([[R(3, 5), sp.I * R(4, 5)],
                            [sp.I * R(4, 5), R(3, 5)]]),
                 sp.Matrix([[R(3, 5), sp.I * R(4, 5)],
                            [sp.I * R(4, 5), R(3, 5)]]))
    rotC = [sp.expand(UC * sp.diag(*[1 if i == a else 0 for i in range(lx)])
                      * UC.H) for a in range(lx)]
    frames_resolve = all(
        is_zero(sp.expand(sum(fr, sp.zeros(lx, lx)) - sp.eye(lx)))
        and all(is_zero(sp.expand(P * P - P)) and is_zero(P - P.H) for P in fr)
        for fr in (rot, rotC))
    rot_add = all(
        sp.expand(sp.trace(gsym * sum((rot[a] for a in blk),
                                      sp.zeros(lx, lx)))
                  - sum(sp.trace(gsym * rot[a]) for a in blk)) == 0
        for part in parts for blk in part)
    out["vacuity"] = {
        "a1_arbitrary_4x4": vac4,
        "a1_arbitrary_8x8": vac8,
        "a1_rotated_frame_real_orthogonal": rot_add,
        "frames_are_resolutions": frames_resolve,
        "gaussian_unitary_frame_measured_for_additivity": False,
        "projector_reading_has_power": not (vac4 and vac8),
    }
    for tag, f in fixes.items():
        cell: dict = {}
        # A1 NUMERIC: additivity over the partition lattice on declared trails.
        lv = f.free_levels[:2]
        trails = [(x1, x2) for x1 in range(f.lx) for x2 in range(f.lx)]
        sample = trails if deep else trails[:4]
        worst, tested = Z0, 0
        for (x1, x2) in sample:
            B = f.B({(lv[0], x1): Z0, (lv[1], x2): Z0})
            tot = sp.expand(sum(B[i, i] for i in range(f.lx)))
            for part in parts:
                for blk in part:
                    lhs = sp.cancel(sum(B[a, a] for a in blk) / tot)
                    rhs = sp.cancel(sum(sp.cancel(B[a, a] / tot) for a in blk))
                    tested += 1
                    d = sp.cancel(lhs - rhs)
                    if sp.Abs(d) > sp.Abs(worst):
                        worst = d
        cell["a1_tests"] = tested
        cell["a1_trails"] = len(sample)
        cell["a1_max_defect"] = worst
        # A2u THE UNION READING: a measure on record configurations, so a
        # disjunction of disjoint records is the SUM BY DEFINITION.
        atoms = {c: f.w([c]) for c in f.cells}
        tot_atoms = sum(atoms.values())
        union_worst = Z0
        for t in f.free_levels:
            lev = tuple((t, x) for x in range(f.lx))
            levtot = sum(atoms[c] for c in lev)
            for part in partitions_of(tuple(range(f.lx))):
                d = sp.cancel((sum(sum(atoms[lev[a]] for a in blk)
                                   for blk in part) - levtot) / tot_atoms)
                if sp.Abs(d) > sp.Abs(union_worst):
                    union_worst = d
        cell["a2u_max_defect"] = union_worst
        # A2c THE JOINT-PIN READING, and THE FORCED SIGN (the checker's L2).
        w_empty = f.w([])
        subs = merge_subsets(f, deep)
        merges = [S for S in subs if len(S) >= 2]
        w_of = {S: f.w(tuple(sorted(S))) for S in merges}
        defects = {S: sp.cancel((w_of[S] - sum(atoms[c] for c in S))
                                / tot_atoms) for S in merges}
        pair_brackets = {bracket(v) for S, v in defects.items() if len(S) == 2}
        top = frozenset(f.cells)
        cell["a2c_merges"] = len(merges)
        cell["a2c_subsets"] = len(subs)
        cell["a2c_nonzero"] = sum(1 for v in defects.values() if v != 0)
        cell["a2c_all_negative"] = all(v < 0 for v in defects.values())
        cell["a2c_max_ratio"] = max(sp.cancel(v / w_empty)
                                    for v in w_of.values())
        cell["a2c_min_atom_sum"] = min(
            sp.cancel(sum(atoms[c] for c in S) / w_empty) for S in merges)
        cell["a2c_bracket_inequality"] = bool(
            cell["a2c_max_ratio"] < R(5, 4)
            and R(5, 4) < 2
            and 2 < cell["a2c_min_atom_sum"])
        cell["a2c_pair_brackets"] = tuple(sorted(pair_brackets))
        cell["a2c_primitive_bracket"] = (tuple(pair_brackets)[0]
                                         if len(pair_brackets) == 1 else None)
        cell["a2c_primitive_is_alphabet_reciprocal"] = (
            len(pair_brackets) == 1
            and tuple(pair_brackets)[0] == A_CELL[tag] + 1)
        cell["a2c_top_bracket"] = bracket(defects[top])
        # A3 THE CROSS-READING -- and THE FORK-ARM IDENTITY, asserted.
        B0 = f.B()
        tot0 = sp.expand(sum(B0[i, i] for i in range(f.lx)))
        p_class = tuple(sp.cancel(B0[a, a] / tot0) for a in range(f.lx))
        wa = [atoms[(f.tstar, a)] for a in range(f.lx)]
        zs = sum(wa)
        mu_pin = tuple(sp.cancel(v / zs) for v in wa)
        # THE TWO ARMS OF BLOCK 171'S LANDED DESIGN_FORK, evaluated at the READ
        # SLOT: the chain-rule conditional reads the class AT the slot being
        # filled; the one-shot Gibbs conditional is the normalized pin weight.
        Bl = f.B({}, level=f.tstar)
        trl = sp.expand(sum(Bl[i, i] for i in range(f.lx)))
        chain_arm = tuple(sp.cancel(Bl[a, a] / trl) for a in range(f.lx))
        gibbs_arm = tuple(sp.cancel(f.w([(f.tstar, a)]) / zs)
                          for a in range(f.lx))
        cell["a3_max_defect"] = max(sp.Abs(sp.cancel(p_class[a] - mu_pin[a]))
                                    for a in range(f.lx))
        cell["a3_bracket"] = bracket(cell["a3_max_defect"])
        cell["a3_p_class_is_chain_arm"] = p_class == chain_arm
        cell["a3_mu_pin_is_gibbs_arm"] = mu_pin == gibbs_arm
        cell["a3_is_the_fork"] = (p_class == chain_arm
                                  and mu_pin == gibbs_arm)
        cell["a3_resolutions_in_play"] = 1
        # THE PIN-IDENTITY READING, corrected: every ratio EXCEEDS 1 and every
        # deviation is at most 1/19, so the sum sits near |A| = 4 trivially.
        ratios = tuple(sp.cancel(v / w_empty) for v in wa)
        cell["a3b_defect"] = sp.cancel(zs / w_empty - 1)
        cell["a3b_in_three_four"] = bool(3 <= cell["a3b_defect"] < 4)
        cell["a3b_all_ratios_exceed_one"] = all(r > 1 for r in ratios)
        cell["a3b_deviation_brackets"] = tuple(bracket(r - 1) for r in ratios)
        cell["a3b_worst_deviation_bracket"] = min(
            cell["a3b_deviation_brackets"])
        # the same comparison on the FREE-CELL alphabet
        Gf = f.free_block()
        tf = sp.expand(sum(Gf[i, i] for i in range(Gf.rows)))
        pc_cell = tuple(sp.cancel(Gf[i, i] / tf) for i in range(Gf.rows))
        zc = tot_atoms
        mp_cell = tuple(sp.cancel(atoms[c] / zc) for c in f.cells)
        cell["a3_cell_bracket"] = bracket(
            max(sp.Abs(sp.cancel(pc_cell[i] - mp_cell[i]))
                for i in range(len(f.cells))))
        out[tag] = cell
    return out


# ---------------------------------------------------------------------------
# D. the non-supply verdict structure, and the A4b genericity
# ---------------------------------------------------------------------------
def verdict_probe(fixes: dict) -> dict:
    """A4b as a GENERIC construction, and the three hypotheses' standing."""
    out: dict = {
        # (H1) and (H2) are NOT SUPPLIED; (H3) is satisfied and inert.  These
        # are DECLARED standings, and the one the checker refuted -- (H2)
        # "measured false" -- is measured here instead of asserted, by the
        # fork-arm identity of gate C.
        "h1_supplied": False,
        "h2_supplied": False,
        "h3_satisfied": True,
        "h2_measured_false": False,
    }
    for tag, f in fixes.items():
        G = f.free_block()
        n = G.rows
        tot = sp.expand(sum(G[i, i] for i in range(n)))
        off = [(i, j) for i in range(n) for j in range(i + 1, n)
               if sp.expand(G[i, j]) != 0]
        rho1 = sp.Matrix(n, n, lambda i, j: sp.cancel(G[i, j] / tot))
        rho2 = sp.diag(*[sp.cancel(G[i, i] / tot) for i in range(n)])
        i, j = off[0]
        phi = sp.Integer(1) if sp.re(sp.expand(rho1[i, j])) != 0 else sp.I
        v = sp.zeros(n, 1)
        v[i], v[j] = R(3, 5), R(4, 5) * phi
        P = sp.expand(v * v.H)
        sep = sp.cancel(sp.expand(sp.trace(rho1 * P))
                        - sp.expand(sp.trace(rho2 * P)))
        closed = sp.cancel(R(12, 25) * (sp.conjugate(phi) * rho1[i, j]
                                        + phi * rho1[j, i]))
        # THE CM-SITE DEGENERACY (the checker's C5 counterpoint): at the bench
        # alphabet the SAME construction collapses, rho1 == rho2 exactly.
        B0 = f.B()
        t0 = sp.expand(sum(B0[a, a] for a in range(f.lx)))
        s1 = sp.Matrix(f.lx, f.lx, lambda a, b: sp.cancel(B0[a, b] / t0))
        s2 = sp.diag(*[sp.cancel(B0[a, a] / t0) for a in range(f.lx)])
        out[tag] = {
            "off_diagonal_pairs": len(off),
            "rho2_is_diag_rho1": all(
                sp.cancel(rho1[k, k] - rho2[k, k]) == 0 for k in range(n)),
            "rho1_rho2_distinct": not is_zero(sp.expand(rho1 - rho2)),
            "rho1_inertia": hermitian_inertia(sp.expand(rho1), f"r1{tag}"),
            "rho2_inertia": hermitian_inertia(sp.expand(rho2), f"r2{tag}"),
            "separation": sep,
            "separation_bracket": bracket(sep),
            "separation_closed_form_matches": sp.cancel(sep - closed) == 0,
            "separation_uses_one_off_diagonal_entry": True,
            "projector_is_resolution_member": is_zero(sp.expand(P * P - P))
            and is_zero(sp.expand(P - P.H)),
            "cm_site_rho1_equals_rho2": is_zero(sp.expand(s1 - s2)),
        }
    return out


# ---------------------------------------------------------------------------
# E. THE STATIONARY KERNEL, and the slot-distance ladder
# ---------------------------------------------------------------------------
def stationarity_points(f: Fix) -> tuple:
    """The DISCLOSED set of (base name, base records, slot) points."""
    if len(f.slots) < 3:
        return ((("empty"), {}, f.slots[0]),)
    s0, s1, s2 = f.slots[0], f.slots[1], f.slots[2]
    return (
        ("empty", {}, s0), ("empty", {}, s1), ("empty", {}, s2),
        ("one-record", {(s0, 0): Z0}, s1),
        ("one-record", {(s0, 0): Z0}, s2),
        ("two-record", {(s0, 0): Z0, (s1, 0): Z0}, s2),
    )


def stationarity_probe(fixes: dict) -> dict:
    out: dict = {}
    for tag, f in fixes.items():
        cell: dict = {}
        for bname, base, ell in stationarity_points(f):
            P0 = f.profile(base)
            Bl = f.B(base, level=ell)
            trl = sp.expand(sum(Bl[i, i] for i in range(f.lx)))
            kappa = tuple(sp.cancel(Bl[a, a] / trl) for a in range(f.lx))
            exts, weights = {}, []
            for a in range(f.lx):
                r = dict(base)
                r[(ell, a)] = Z0
                exts[a] = f.profile(r)
                weights.append(f.env(r).trace(BEST, f.tstar))
            zs = sum(weights)
            nu = tuple(sp.cancel(v / zs) for v in weights)
            row = {"slot": ell, "distance": f.tstar - ell}
            for name, mu in (("gibbs", nu), ("chain", kappa)):
                push = tuple(sp.cancel(sum(mu[a] * exts[a][b]
                                           for a in range(f.lx)))
                             for b in range(f.lx))
                dv = tuple(sp.cancel(push[b] - P0[b]) for b in range(f.lx))
                mx = max(dv, key=lambda v: sp.Abs(v))
                row[name] = {
                    "mu_sums_to_one": sp.expand(sum(mu) - 1) == 0,
                    "push_sums_to_one": sp.expand(sum(push) - 1) == 0,
                    "stationary": all(v == 0 for v in dv),
                    "max_defect_bracket": bracket(mx),
                }
            row["arms_differ"] = nu != kappa
            # THE STATIONARY SYSTEM, treated as an UNKNOWN mu:
            #   sum_a mu_a P(. | t + (ell,a)) = P(. | t),  sum_a mu_a = 1
            M = sp.Matrix(f.lx + 1, f.lx,
                          lambda i, j: exts[j][i] if i < f.lx
                          else sp.Integer(1))
            rhs = sp.Matrix(list(P0) + [sp.Integer(1)])
            rank = M.rank()
            solutions = sp.linsolve((M, rhs))
            solution = (sp.Matrix(tuple(solutions)[0])
                        if len(solutions) == 1 else None)
            residual = (tuple(sp.cancel(v) for v in (M * solution - rhs))
                        if solution is not None else None)
            row["system"] = {
                "rank": int(rank),
                "unknowns": f.lx,
                "equations": f.lx + 1,
                "unique": bool(rank == f.lx and solution is not None),
                "strictly_positive": bool(
                    solution is not None
                    and all(v > 0 for v in solution)),
                "sums_to_one": bool(
                    solution is not None
                    and sp.expand(sum(solution) - 1) == 0),
                "residual_zero": bool(
                    residual is not None and all(v == 0 for v in residual)),
                "mu_star_brackets": (tuple(bracket(v) for v in solution)
                                     if solution is not None else None),
                "mu_star_is_an_arm": bool(
                    solution is not None
                    and (tuple(solution) == nu or tuple(solution) == kappa)),
            }
            cell[(bname, ell)] = row
        out[tag] = cell
    return out


def ladder_facts(stationarity: dict) -> dict:
    """The slot-distance ladder and the fixed-slot base-invariance."""
    bench = stationarity[BENCH_TAG]
    ladder = tuple(bench[("empty", ell)]["gibbs"]["max_defect_bracket"]
                   for ell in LADDER_SLOTS)
    chain_ladder = tuple(bench[("empty", ell)]["chain"]["max_defect_bracket"]
                         for ell in LADDER_SLOTS)
    # THE CONFOUND, isolated: hold the SLOT fixed and vary the base length over
    # {0, 1} -- exactly the comparison the solve confounded with a slot move.
    worst_num, worst_den = 0, 1
    cells = 0
    for ell in LADDER_SLOTS:
        for form in ("gibbs", "chain"):
            got = [row[form]["max_defect_bracket"]
                   for (bname, slot), row in bench.items()
                   if slot == ell and bname in ("empty", "one-record")]
            if len(got) < 2:
                continue
            cells += 1
            spread, low = max(got) - min(got), min(got)
            if spread * worst_den > worst_num * low:
                worst_num, worst_den = spread, low
    return {
        "ladder": ladder,
        "chain_ladder": chain_ladder,
        "strictly_decreasing_bracket": all(
            ladder[i] > ladder[i + 1] for i in range(len(ladder) - 1)),
        "slot_factor": R(int(ladder[0]), int(ladder[-1])),
        "base_cells_compared": cells,
        "worst_base_spread": R(worst_num, worst_den),
        "base_invariance_under_one_fortieth": R(worst_num, worst_den) < R(1, 40),
    }


# ---------------------------------------------------------------------------
# F. THE S-DIAG THEOREM
# ---------------------------------------------------------------------------
def sdiag_symbolic_8x4() -> bool:
    """S-DIAG at 8x4 with ALL EIGHT free shears as FREE REAL SYMBOLS.

    DomainMatrix inverse over QQ(z).  Measured at 637 s by the disjoint checker
    and re-measured independently at about 800 s by this draft worker, which is
    why this leg runs under --deep only; at baseline S-DIAG is gated by the
    all-level NUMERIC census.  The 12x4 symbolic leg is UNFINISHED and is
    disclosed as such -- a mutation asserts it and must fail gate F.
    """
    s = b171.Site("8x4", 8, 4)
    cells = tuple((t, x) for t in s.free_levels for x in range(s.lx))
    symbols = {c: sp.Symbol(f"z_{c[0]}_{c[1]}", real=True) for c in cells}
    Q = sp.expand(s.bench.Q.subs(s.sub(records=symbols)))
    if len(Q.free_symbols) != len(cells):
        return False
    Qi = DomainMatrix.from_Matrix(Q).to_field().inv().to_Matrix()
    for level in range(s.T):
        rows = [s.lx * (level % s.T) + x for x in range(s.lx)]
        for i in range(s.lx):
            for j in range(s.lx):
                if i == j:
                    continue
                entry = sp.cancel(sp.together(
                    (Qi[rows[i], rows[j]]
                     + sp.conjugate(Qi[rows[j], rows[i]])) / 2))
                if entry != 0:
                    return False
    return True


def sdiag_probe(fixes: dict, deep: bool) -> dict:
    out: dict = {}
    for tag, f in fixes.items():
        s = f.site

        def all_levels_diagonal(env) -> bool:
            for level in range(s.T):
                B = env.block(BEST, level)
                for i in range(f.lx):
                    for j in range(f.lx):
                        if i != j and sp.expand(B[i, j]) != 0:
                            return False
            return True

        carriers = {mode: all_levels_diagonal(f.env({}, mode=mode))
                    for mode in ("xgraded", "flat", "graded")}
        dials = {"st_dial": all_levels_diagonal(f.env({}, st=R(1, 8)))}
        for name, Qd in (("holo_t", s.Q_holo_t), ("holo_x", s.Q_holo_x)):
            Qn = sp.expand(Qd.subs(s.sub()).subs(b171.DIAL))
            dials[name] = all_levels_diagonal(b171.Env(s, Qn, name))
        rng = random.Random(SDIAG_SEED)
        hits = 0
        for _ in range(SDIAG_RANDOM_POINTS):
            recs = {c: R(rng.randint(1, 9), rng.randint(11, 19))
                    for c in f.cells}
            if all_levels_diagonal(f.env(recs)):
                hits += 1
        # THE FREE-CELL BLOCK: off-diagonal support strictly CROSS-LEVEL.
        G = f.free_block()
        n = G.rows
        off = [(i, j) for i in range(n) for j in range(i + 1, n)
               if sp.expand(G[i, j]) != 0]
        # NOT A BASIS ARTIFACT: Q is neither level-block-diagonal nor
        # level-diagonal, so CM-SITE is not the eigenbasis by construction.
        Qn = sp.expand(s.bench.Q.subs(s.sub()))
        rows_ts = [s.lx * (s.tstar % s.T) + x for x in range(s.lx)]
        q_level_block_diagonal = all(
            Qn[p, q] == 0 for p in rows_ts for q in range(s.N)
            if q not in rows_ts)
        q_level_diagonal = all(
            Qn[rows_ts[i], rows_ts[j]] == 0
            for i in range(s.lx) for j in range(s.lx) if i != j)
        out[tag] = {
            "levels": s.T,
            "carriers": carriers,
            "dials": dials,
            "random_points": SDIAG_RANDOM_POINTS,
            "random_hits": hits,
            "all_levels_everywhere": all(carriers.values())
            and all(dials.values()) and hits == SDIAG_RANDOM_POINTS,
            "read_slice_only": False,
            "free_cell_off_pairs": len(off),
            "off_support_cross_level_only": all(
                f.cells[i][0] != f.cells[j][0] for i, j in off),
            "q_level_block_diagonal": q_level_block_diagonal,
            "q_level_diagonal": q_level_diagonal,
            "not_a_basis_artifact": not q_level_block_diagonal
            and not q_level_diagonal,
        }
    out["symbolic"] = {
        "8x4": sdiag_symbolic_8x4() if deep else None,
        "8x4_run": bool(deep),
        # THE 12x4 SYMBOLIC LEG IS UNFINISHED, at BOTH settings, DISCLOSED.
        "12x4": None,
        "12x4_run": False,
        "extents_proved_symbolically": ("8x4",) if deep else (),
        "extents_claimable_symbolically": ("8x4",),
    }
    return out


