# the measurement pass
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class Facts:
    main_head: str
    authority: AuthorityCertificate
    banners: dict
    census: dict
    verdict: dict
    stationarity: dict
    ladder: dict
    sdiag: dict
    controls: dict
    scope: dict
    note_at_final_path: bool
    exact_no_float: bool
    source_floats: int
    source_forbidden: int
    deep: bool


def measure(deep: bool) -> Facts:
    main_head = resolve_ref("origin/main")
    fixes = {tag: Fix(tag, ct, lx) for tag, ct, lx in PRIMARY}
    banners = banner_probe(fixes)
    census = census_probe(fixes, deep)
    verdict = verdict_probe(fixes)
    stationarity = stationarity_probe(fixes)
    ladder = ladder_facts(stationarity)
    sdiag = sdiag_probe(fixes, deep)
    controls = controls_probe(fixes)

    def harvest(node):
        if isinstance(node, dict):
            for key, value in node.items():
                harvest(key)
                harvest(value)
        elif isinstance(node, (tuple, list, frozenset, set)):
            for value in node:
                harvest(value)
        elif isinstance(node, (sp.Basic, int)) and not isinstance(node, bool):
            record(node)

    for block in (banners, census, verdict, stationarity, ladder, sdiag,
                  controls):
        harvest(block)
    exact = all(no_float(value) for value in NUMERALS)
    text, at_final = raw_note()
    return Facts(main_head, authority_certificate(main_head), banners, census,
                 verdict, stationarity, ladder, sdiag, controls,
                 scope_certificate(text), at_final, exact,
                 source_float_literals(), source_forbidden_calls(), deep)


