# ---------------------------------------------------------------------------
# claims: the only thing a mutation is allowed to touch
# ---------------------------------------------------------------------------
def build_claims(mutation: str) -> dict:
    claims: dict = {
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        "provenance_rows_match": True,
        "projector_reading_has_power": False,
        "a2c_sign_free": False,
        "h2_measured_false": False,
        "a4b_structural": False,
        "stationary_kernel_exists": True,
        "defect_grows_with_trail": False,
        "slot_ladder": EXPECTED_LADDER,
        "sdiag_symbolic_extents": ("8x4",),
        "sdiag_all_levels": True,
        "control_bench_empty_on_homogeneous": True,
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "claim_provenance_rows_differ":
        # THE PROVENANCE GATE DENIED: the corrected Block 171 profile table
        # asserted NOT to reproduce, which the 32-of-32 entry-for-entry rebuild
        # off the committed chain forbids.
        claims["provenance_rows_match"] = False
    elif mutation == "drop_vacuity_structure":
        # THE VACUITY FINDING DENIED: the projector reading asserted to carry
        # discriminating power, which the symbolic identity in the free entries
        # of an ARBITRARY 4x4 and 8x8 matrix forbids.
        claims["projector_reading_has_power"] = True
    elif mutation == "claim_a2c_sign_free":
        # THE FORCED SIGN DENIED: some merge asserted to have a non-negative
        # defect, which the exact bracket max_S w(S) < (5/4) w(empty) <
        # 2 w(empty) < min_S sum_c w(c) forbids at both extents.
        claims["a2c_sign_free"] = True
    elif mutation == "claim_noncontextuality_measured_false":
        # THE SOLVE'S ORIGINAL READING RE-ASSERTED: (H2) asserted MEASURED
        # FALSE, which the entry-for-entry identity of the two readings with
        # Block 171's two landed DESIGN_FORK arms forbids -- one resolution of
        # the identity, two functionals, so (H2) is NOT SUPPLIED.
        claims["h2_measured_false"] = True
    elif mutation == "claim_a4b_structural":
        # THE IDENTIFIABILITY WITNESS RE-INFLATED: the rho1/rho2 pair asserted
        # structural rather than generic, which rho2 == diag(rho1) forbids.
        claims["a4b_structural"] = True
    elif mutation == "claim_no_stationary_kernel":
        # THE SOLVE'S REFUTED SENTENCE RE-ASSERTED: no fixed point asserted to
        # exist, which the rank-4 system's unique strictly-positive zero-residual
        # mu* at every measured base, slot and extent forbids.
        claims["stationary_kernel_exists"] = False
    elif mutation == "claim_trail_growth":
        # THE REFUTED CONFOUND RE-ASSERTED: the defect asserted to grow with the
        # base trail, which the fixed-slot base invariance forbids.
        claims["defect_grows_with_trail"] = True
    elif mutation == "break_slot_ladder":
        # THE EXACT LADDER BROKEN by one unit at the nearest slot.
        claims["slot_ladder"] = (EXPECTED_LADDER[0], EXPECTED_LADDER[1],
                                 EXPECTED_LADDER[2] + 1)
    elif mutation == "claim_sdiag_symbolic_12x4":
        # THE UNFINISHED LEG ASSERTED: S-DIAG claimed symbolically at 12x4,
        # which this block did not run and discloses as unfinished.
        claims["sdiag_symbolic_extents"] = ("8x4", "12x4")
    elif mutation == "claim_sdiag_read_slice_only":
        # THE UPGRADE DENIED: diagonality asserted only at the read slice, which
        # the all-level measurement at both extents forbids.
        claims["sdiag_all_levels"] = False
    elif mutation == "claim_control_bench_nonempty":
        # THE NULL CONTROL DENIED: the candidate asserted non-uniform on the
        # x-homogeneous carriers, which its exact (1/4,1/4,1/4,1/4) profile
        # there -- Block 171's landed lemma L2 -- forbids.
        claims["control_bench_empty_on_homogeneous"] = False
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim")
    elif mutation == "drop_owner_bar":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key not in OWNER_KEYS)
    return claims


